type ArtifactTaskKind = '起' | '转' | '合'

interface ArtifactTaskData {
  kind: ArtifactTaskKind
  name: string
  difficulty: string
  /** 一句话备战摘要（用于 summary）；详细清单见可选的 prep */
  prepare: string
  /** 详细备战清单（物品/装备/召唤兽）。缺省时回退到 prepare 单行 */
  prep?: string[]
  route: string[]
  tips: string[]
  recommend: string[]
  /** 配图（怪物分布/机制标注等，压缩后打包进 public/guide-img/） */
  images?: GuideImage[]
  source?: string
}

